package com.yeyamo_mobile.api.payment_service.infrastructure.web;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest@AutoConfigureMockMvc class AdminPaymentSecurityTest{@Autowired MockMvc mvc;@Test void anonymousCannotList()throws Exception{mvc.perform(get("/api/v1/payments/admin")).andExpect(status().isUnauthorized());}@Test void regularAdminCannotStartReconciliation()throws Exception{mvc.perform(post("/api/v1/payments/admin/reconciliation").with(jwt().authorities(()->"ROLE_ADMIN"))).andExpect(status().isForbidden());}}
